        """
        Builds an index from the given array and tokenizer.

        Args:
        :param array: Iterable, the array of strings to be indexed.
        :param tokenizer: A function used for tokenizing the strings in the array.
        :param truncate: bool, indicates whether to truncate the data to fit within memory constraints.
        :param batch_size: int, the size of batches to process the array in.
        :param avoid_copies: bool, indicates whether to avoid making copies of the data to save memory.
        :return: An instance of SearchArray, which contains the indexed data including term matrix, positions, term dictionary, average document length, and document lengths.
        """
        term_dict = {}
        doc_lens = np.zeros(len(array), dtype=int)
        posns = {term: {} for term in term_dict}

