from typing import Iterable, Optional, Dict
import numpy as np

class SearchArray:
    def __init__(self,
                 postings,
                 doc_len: int = 0,
                 posns: Optional[Dict] = None,
                 encoded=False):
        # Initialize SearchArray instance
        self.postings = postings
        self.doc_len = doc_len
        self.posns = posns
        self.encoded = encoded

    @classmethod
    def term_dict(cls) -> Dict:
        # Return the term dictionary
        return cls.postings.term_dict

    @classmethod
    def doc_lens(cls) -> np.ndarray:
        # Return the document lengths
        return cls.postings.doc_lens

    @classmethod
    def ws_tokenizer(cls, string: str) -> list:
        # Tokenize the string using whitespace as the delimiter
        return string.split()

    @classmethod
    def index(cls, array: Iterable, tokenizer=ws_tokenizer,
              truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':
        """
        Indexes an array of strings using a specified tokenizer and returns an instance of SearchArray containing the indexed data.

        Input-Output Arguments
        :param cls: The class SearchArray itself. It is used to create a new instance of SearchArray that will hold the indexed data.
        :param array: Iterable, the array of strings to be indexed. It is the input data that needs to be processed and indexed.
        :param tokenizer: A function used for tokenizing the strings in the array. It defaults to ws_tokenizer if not specified.
        :param truncate: bool, indicates whether to truncate the data to fit within memory constraints. It defaults to False, meaning the data will not be truncated unless specified.
        :param batch_size: int, the size of batches to process the array in. This is useful for processing large arrays without loading everything into memory at once. Defaults to 100000.
        :param avoid_copies: bool, indicates whether to avoid making copies of the data to save memory. Defaults to True, optimizing memory usage during the indexing process.
        :return: An instance of SearchArray, which contains the indexed data including term matrix, positions, term dictionary, average document length, and document lengths.
        """

        # Initialize the term dictionary and postings
        term_dict = {}
        postings = {'term_dict': term_dict}

        # Initialize the document lengths and positions
        doc_lens = np.zeros(len(array), dtype=int)
        posns = {i: {} for i in range(len(array))}

        # Process the array in batches if necessary
        for i in range(0, len(array), batch_size):
            batch = array[i:i+batch_size]

            # Tokenize the batch using the specified tokenizer
            tokens = [tokenizer(string) for string in batch]

            # Update the term dictionary and postings
            for token in tokens:
                for j, term in enumerate(token):
                    if term not in term_dict:
                        term_dict[term] = len(term_dict)
                    doc_lens[i//batch_size] += 1
                    if term not in posns[i//batch_size]:
                        posns[i//batch_size][term] = []
                    posns[i//batch_size][term].append(j)

        # Create a new instance of SearchArray
        search_array = cls(postings, doc_len=np.mean(doc_lens), posns=posns, encoded=True)

        return search_array

