import pandas as pd
import numpy as np
from typing import List, Optional
from nltk.tokenize import word_tokenize
from nltk.corpus import stopwords
from nltk.stem import WordNetLemmatizer
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity

class Similarity:
    def __init__(self, vectorizer):
        self.vectorizer = vectorizer

    def compute_similarity(self, query_vector, doc_vector):
        return cosine_similarity(query_vector, doc_vector)

class DefaultBM25(Similarity):
    def __init__(self):
        super().__init__(TfidfVectorizer())

def parse_query_terms(q: str, qf: List[str], nlp):
    query_terms = {}
    for field in qf:
        terms = word_tokenize(q)
        terms = [term for term in terms if term.isalpha()]
        terms = [lemmatizer.lemmatize(term) for term in terms]
        terms = [term for term in terms if term not in stopwords.words('english')]
        query_terms[field] = terms
    return query_terms

def parse_field_boosts(qf: List[str], q: str):
    field_boosts = {}
    for field in qf:
        if f'boost({field})' in q:
            start = q.find(f'boost({field})') + len(f'boost({field})')
            end = q.find('}', start)
            field_boosts[field] = float(q[start:end])
        else:
            field_boosts[field] = 1.0
    return field_boosts

def _edismax_term_centric(frame: pd.DataFrame,
                          query_terms: dict,
                          field_boosts: dict,
