        # Initialize the SearchArray instance with empty attributes
        self.term_matrix = []
        self.positions = {}
        self.term_dict = {}
        self.avg_doc_length = 0
        self.doc_lengths = []

    @classmethod
    def index(cls, array: Iterable, tokenizer=lambda x: x.split(), truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':
        """
        Indexes an array of strings using a specified tokenizer and returns an instance of SearchArray containing the indexed data.

        Input-Output Arguments
        :param cls: The class SearchArray itself. It is used to create a new instance of SearchArray that will hold the indexed data.
        :param array: Iterable, the array of strings to be indexed. It is the input data that needs to be processed and indexed.
        :param tokenizer: A function used for tokenizing the strings in the array. It defaults to a simple split tokenizer if not specified.
        :param truncate: bool, indicates whether to truncate the data to fit within memory constraints. It defaults to False, meaning the data will not be truncated unless specified.
        :param batch_size: int, the size of batches to process the array in. This is useful for processing large arrays without loading everything into memory at once. Defaults to 100000.
        :param avoid_copies: bool, indicates whether to avoid making copies of the data to save memory. Defaults to True, optimizing memory usage during the indexing process.
        :return: An instance of SearchArray, which contains the indexed data including term matrix, positions, term dictionary, average document length, and document lengths.
        """

        # Create a new instance of SearchArray
        indexed_array = cls()

        # Check if the input array is list-like
        if not hasattr(array, '__iter__'):
            raise TypeError("Input array must be iterable")

        # Process the array in batches if necessary
        for i in range(0, len(array), batch_size):
            batch = array[i:i + batch_size]

            # Tokenize the batch using the specified tokenizer
            tokens = [tokenizer(doc) for doc in batch]

            # Build an index from the tokens
            indexed_array.build_index_from_tokenizer(tokens, truncate, avoid_copies)

        return indexed_array

    def build_index_from_tokenizer(self, tokens, truncate=False, avoid_copies=True):
        # Create a term dictionary
        self.term_dict = {}
        for token in tokens:
            for t in token:
                if t not in self.term_dict:
                    self.term_dict[t] = len(self.term_dict)

        # Create a term matrix and positions
        self.term_matrix = []
        self.positions = {}
        for i, token in enumerate(tokens):
            if avoid_copies:
                token = list(token)
            self.term_matrix.append([self.term_dict[t] for t in token])
            for j, t in enumerate(token):
                if t not in self.positions:
                    self.positions[t] = [i, j]
                else:
                    self.positions[t].append(i)

        # Calculate the average document length
        self.avg_doc_length = sum(len(doc) for doc in tokens) / len(tokens)

        # Calculate the document lengths
        self.doc_lengths = [len(doc) for doc in tokens]

