    :return: torch.Tensor. The input batch converted to a CUDA tensor, ready for GPU processing.
    """

    # Check if the input batch is a PyTorch tensor and move it to the specified device
    if isinstance(batch, torch.Tensor):
        return batch.to(device, non_blocking=True)

    # If the input batch is a tuple or list, recursively apply the to_cuda function to each element
    elif isinstance(batch, (tuple, list)):
        # If ignore_list is True, return a list of None values with the same length as the input batch
        if ignore_list:
