import torch
import numpy as np
from dotmap import dotmap

def add_batch(batch):
    """
    This function recursively adds a new dimension to the input data structure at the zeroth position.

    :param batch: Union[tuple, list, dict, torch.Tensor, np.ndarray]. The input data which can be a single item or a batch of items in various formats.
    :return: Union[torch.Tensor, np.ndarray]. The modified batch with an added dimension at the zeroth position.
    """

    # Base case: if the batch is already a tensor or numpy array, add a new dimension
    if isinstance(batch, (torch.Tensor, np.ndarray)):
        return np.expand_dims(batch, axis=0) if isinstance(batch, np.ndarray) else batch.unsqueeze(0)

    # Check the type of the input `batch`
    if isinstance(batch, torch.Tensor):
        # If `batch` is a torch.Tensor, convert it to the desired device (if necessary) and add a new dimension using the `unsqueeze()` method
        return batch.unsqueeze(0)
    elif isinstance(batch, np.ndarray):
        # If `batch` is a numpy.ndarray, convert it to a torch.Tensor using `torch.as_tensor()` and add a new dimension using the `unsqueeze()` method
        return torch.as_tensor(batch).unsqueeze(0)
    elif isinstance(batch, (tuple, list)):
        # If `batch` is a tuple or list, recursively apply the `add_batch()` function to each element in the batch
        return tuple(add_batch(b) for b in batch)
    elif isinstance(batch, dict):
        # If `batch` is a dictionary, recursively apply the `add_batch()` function to each value in the dictionary
        batch = dotmap({k: add_batch(v) for k, v in batch.items()})
        return batch
    else:
        # If `batch` is not a supported type, raise a TypeError
        raise TypeError("Unsupported type for batch: {}".format(type(batch)))

