        return np.expand_dims(batch, axis=0) if isinstance(batch, np.ndarray) else batch.unsqueeze(0)

    # Recursive case: apply the same operation to each element in the batch
    if isinstance(batch, (tuple, list)):
        return tuple(add_batch(b) for b in batch)
    elif isinstance(batch, dict):
        return DotMap({k: add_batch(v) for k, v in batch.items()})
    elif isinstance(batch, torch.Tensor):
        batch = batch.to(device, non_blocking=True)
    else:  # numpy and others
        batch = torch.as_tensor(batch, device=device)
    return batch

