    if isinstance(batch, (tuple, list)):
        return [add_batch(b) for b in batch]

    # If batch is a dictionary, recursively apply the function to each value
    elif isinstance(batch, dict):
        return dotmap({k: add_batch(v) for k, v in batch.items()})

