        return tuple(to_cuda(elem, device, ignore_list) for elem in batch) if not ignore_list else tuple(to_cuda(elem, device, ignore_list) for elem in batch if elem is not ignore_list)

    elif isinstance(batch, dict):
        new_batch = {}
        for key, value in batch.items():
            if key == "meta":
                new_batch[key] = value
            else:
                new_batch[key] = to_cuda(value, device, ignore_list)
        return dotdict(new_batch)

